import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** Selects a repository descriptor without changing the active settings. */
public final class SettingsPresetPickerActivity extends Activity {
    public static final String EXTRA_KIND="kind",EXTRA_ID="preset_id";
    private final ExecutorService worker=Executors.newSingleThreadExecutor(r->new Thread(r,"preset-picker"));
    private final Handler main=new Handler(Looper.getMainLooper());
    private GlassUi ui;private FrameLayout root;private TextView status,retry;private ProgressBar progress;private ListView list;private EditText search;private Rows adapter;
    private String kind,selectedId,query="";private List<Entry> all=Collections.emptyList();private int generation;private boolean loaded,destroyed;private Runnable pendingFilter;private Object backCallback;
    private static final class Entry {final PresetRepository.Preset preset;final String search,group;Entry(PresetRepository.Preset p,String synonyms,String group){preset=p;this.group=group;search=((p.name==null?"":p.name)+" "+(p.vendor==null?"":p.vendor)+" "+p.kind+" "+(p.system?"system системный":"user пользовательский")+" "+synonyms+" "+group).toLowerCase(Locale.ROOT);}Entry(String heading){preset=null;group=heading;search="";}}
    @Override protected void onCreate(Bundle state){super.onCreate(state);kind=getIntent().getStringExtra(EXTRA_KIND);selectedId=getIntent().getStringExtra(EXTRA_ID);if(state!=null)query=state.getString("query","");if(android.os.Build.VERSION.SDK_INT>=33)backCallback=Api33.register(this);build();if(validKind())load();else setError(getString(R.string.phase2_picker_invalid),false);}
    @Override protected void onSaveInstanceState(Bundle state){state.putString("query",query);super.onSaveInstanceState(state);}
    @Override protected void onDestroy(){destroyed=true;generation++;if(pendingFilter!=null)main.removeCallbacks(pendingFilter);worker.shutdownNow();if(android.os.Build.VERSION.SDK_INT>=33&&backCallback!=null)Api33.unregister(this,backCallback);super.onDestroy();}
    @android.annotation.TargetApi(33) private static final class Api33 {static Object register(SettingsPresetPickerActivity a){android.window.OnBackInvokedCallback callback=a::finish;a.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,callback);return callback;}static void unregister(SettingsPresetPickerActivity a,Object callback){a.getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback((android.window.OnBackInvokedCallback)callback);}}
    private boolean validKind(){return PresetRepository.PROCESS.equals(kind)||PresetRepository.FILAMENT.equals(kind)||PresetRepository.PRINTER.equals(kind);}
    private int title(){return PresetRepository.PROCESS.equals(kind)?R.string.phase2_picker_process:PresetRepository.FILAMENT.equals(kind)?R.string.phase2_picker_filament:PresetRepository.PRINTER.equals(kind)?R.string.phase2_picker_printer:R.string.phase2_picker_title;}
    private void build(){
        root=new FrameLayout(this);root.setBackground(GlassBackground.create(this));setContentView(root);getWindow().setStatusBarColor(Color.rgb(74,79,89));getWindow().setNavigationBarColor(Color.rgb(74,79,89));getWindow().getDecorView().setSystemUiVisibility(0);if(android.os.Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,in)->{android.graphics.Insets x=in.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout());v.setPadding(x.left,x.top,x.right,x.bottom);return in;});ui=new GlassUi(this,root,false);
        LinearLayout page=ui.vertical();page.setFocusableInTouchMode(true);page.requestFocus();ui.pad(page,20,28,20,16);root.addView(page,new FrameLayout.LayoutParams(-1,-1));FrameLayout bar=new FrameLayout(this);page.addView(bar,new LinearLayout.LayoutParams(-1,ui.dp(44)));TextView heading=ui.heading(getString(title()));heading.setGravity(Gravity.CENTER);bar.addView(heading,new FrameLayout.LayoutParams(-2,-1,Gravity.CENTER));ImageView back=new ImageView(this);back.setImageDrawable(GlassIcon.create(this,"back",ui.tokens.textPrimary));back.setBackground(GlassSurface.of(this,ui.tokens.pillRadiusMax,false));back.setPadding(ui.dp(12),ui.dp(12),ui.dp(12),ui.dp(12));back.setContentDescription(getString(R.string.phase2_picker_back));back.setFocusable(true);back.setOnClickListener(v->finish());bar.addView(back,new FrameLayout.LayoutParams(ui.dp(44),ui.dp(44),Gravity.START|Gravity.CENTER_VERTICAL));
        ui.space(page,12);LinearLayout input=ui.horizontal();ui.pad(input,12,0,12,0);ImageView icon=new ImageView(this);icon.setImageDrawable(GlassIcon.create(this,"search",ui.tokens.textSecondary));icon.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);input.addView(icon,new LinearLayout.LayoutParams(ui.dp(22),ui.dp(22)));search=ui.edit(query,android.text.InputType.TYPE_CLASS_TEXT,false);search.setHint(R.string.phase2_picker_search);search.setContentDescription(getString(R.string.phase2_picker_search));search.setBackground(null);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(0,-2,1);ep.leftMargin=ui.dp(10);input.addView(search,ep);page.addView(ui.surface(input,ui.tokens.pillRadiusMax),new LinearLayout.LayoutParams(-1,ui.dp(52)));
        ui.space(page,12);FrameLayout area=new FrameLayout(this);page.addView(area,new LinearLayout.LayoutParams(-1,0,1));list=new ListView(this);list.setDivider(null);list.setDividerHeight(0);list.setVerticalScrollBarEnabled(false);list.setClipToPadding(false);adapter=new Rows();list.setAdapter(adapter);list.setOnItemClickListener((parent,view,position,id)->{Entry entry=adapter.item(position);if(entry.preset==null)return;setResult(RESULT_OK,new Intent().putExtra(EXTRA_ID,entry.preset.id));finish();});area.addView(list,new FrameLayout.LayoutParams(-1,-1));
        LinearLayout state=ui.vertical();state.setGravity(Gravity.CENTER);progress=new ProgressBar(this);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(ui.tokens.textPrimary));state.addView(progress,new LinearLayout.LayoutParams(ui.dp(40),ui.dp(40)));status=ui.text("",14,400,ui.tokens.textPrimary);status.setGravity(Gravity.CENTER);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=ui.dp(12);state.addView(status,sp);retry=ui.action(getString(R.string.phase2_picker_retry),false,this::load);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-2,-2);rp.topMargin=ui.dp(12);state.addView(retry,rp);area.addView(state,new FrameLayout.LayoutParams(-1,-1));state.setTag("state");
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();scheduleFilter();}public void afterTextChanged(Editable e){}});
    }
    private View state(){return ((ViewGroup)list.getParent()).findViewWithTag("state");}
    private void setLoading(){state().setVisibility(View.VISIBLE);list.setVisibility(View.GONE);progress.setVisibility(View.VISIBLE);retry.setVisibility(View.GONE);status.setText(R.string.phase2_picker_loading);}
    private void setError(String message,boolean canRetry){state().setVisibility(View.VISIBLE);list.setVisibility(View.GONE);progress.setVisibility(View.GONE);retry.setVisibility(canRetry?View.VISIBLE:View.GONE);status.setText(getString(R.string.phase2_picker_error)+"\n"+message);}
    private void load(){if(!validKind())return;loaded=false;final int token=++generation;if(pendingFilter!=null)main.removeCallbacks(pendingFilter);setLoading();worker.execute(()->{try{PresetRepository repository=SettingsState.repository(getApplicationContext());List<PresetRepository.Preset> presets=repository.list(kind);ArrayList<Entry> data=new ArrayList<>(presets.size());String synonyms=getString(title());boolean filament=PresetRepository.FILAMENT.equals(kind);String mode=GeneralPreferences.prefs(this).getString("group_filament_presets","all");for(PresetRepository.Preset p:presets){if(Thread.currentThread().isInterrupted())return;String group="";if(filament&&!p.system){org.json.JSONObject effective=("type".equals(mode)||"vendor".equals(mode))?repository.resolve(p.id):null;group=GeneralPreferences.filamentGroup(this,p.name,effective,p.vendor);if(group.isEmpty()&&!"none".equals(mode))group=getString(R.string.pref_group_unspecified);}data.add(new Entry(p,synonyms,group));}if(filament&&!"none".equals(mode))data.sort((a,b)->{if(a.preset.system!=b.preset.system)return a.preset.system?1:-1;if(a.preset.system)return 0;int group=a.group.compareToIgnoreCase(b.group);return group!=0?group:a.preset.name.compareToIgnoreCase(b.preset.name);});main.post(()->{if(destroyed||token!=generation)return;all=Collections.unmodifiableList(data);loaded=true;scheduleFilter();});}catch(Exception e){String message=e.getMessage();main.post(()->{if(!destroyed&&token==generation)setError(message==null?e.getClass().getSimpleName():message,true);});}});}
    private void scheduleFilter(){if(!loaded)return;if(pendingFilter!=null)main.removeCallbacks(pendingFilter);final int token=++generation;final String sought=query.trim().toLowerCase(Locale.ROOT);pendingFilter=()->worker.execute(()->{ArrayList<Entry> matches=new ArrayList<>();String previous="";for(Entry item:all){if(Thread.currentThread().isInterrupted())return;if(sought.isEmpty()||item.search.contains(sought)){if(!item.group.isEmpty()&&!item.group.equals(previous))matches.add(new Entry(item.group));previous=item.group;matches.add(item);}}main.post(()->{if(destroyed||token!=generation)return;adapter.setItems(matches);boolean empty=matches.isEmpty();state().setVisibility(empty?View.VISIBLE:View.GONE);list.setVisibility(empty?View.GONE:View.VISIBLE);if(empty){progress.setVisibility(View.GONE);retry.setVisibility(View.GONE);status.setText(R.string.phase2_picker_empty);}});});main.postDelayed(pendingFilter,150);}
    private final class Rows extends BaseAdapter {private List<Entry> visible=Collections.emptyList();void setItems(List<Entry> items){visible=items;notifyDataSetChanged();}Entry item(int p){return visible.get(p);}@Override public int getCount(){return visible.size();}@Override public Object getItem(int p){return item(p);}@Override public long getItemId(int p){return p;}
        @Override public int getViewTypeCount(){return 2;}@Override public int getItemViewType(int p){return item(p).preset==null?1:0;}@Override public boolean areAllItemsEnabled(){return false;}@Override public boolean isEnabled(int p){return item(p).preset!=null;}
        @Override public View getView(int position,View recycled,ViewGroup parent){if(item(position).preset==null){TextView heading=recycled instanceof TextView?(TextView)recycled:ui.section("");heading.setText(item(position).group);ui.pad(heading,8,12,8,8);return heading;}RowHolder holder;if(recycled==null){LinearLayout outer=ui.vertical();ui.pad(outer,0,0,0,6);LinearLayout body=ui.vertical();ui.pad(body,16,10,16,10);body.setMinimumHeight(ui.dp(64));holder=new RowHolder();holder.body=body;holder.name=ui.text("",14,600,ui.tokens.textPrimary);holder.name.setMaxLines(3);holder.detail=ui.text("",12,400,ui.tokens.textSecondary);LinearLayout.LayoutParams detail=new LinearLayout.LayoutParams(-1,-2);detail.topMargin=ui.dp(4);body.addView(holder.name);body.addView(holder.detail,detail);outer.addView(body,new LinearLayout.LayoutParams(-1,-2));outer.setTag(holder);recycled=outer;}else holder=(RowHolder)recycled.getTag();PresetRepository.Preset p=item(position).preset;boolean selected=p.id.equals(selectedId);holder.name.setText(p.name);String type=getString(p.system?R.string.phase2_picker_system:R.string.phase2_picker_user);holder.detail.setText((p.vendor==null||p.vendor.isEmpty()?"":p.vendor+" · ")+type+(selected?" · "+getString(R.string.phase2_picker_selected):""));if(selected){android.graphics.drawable.GradientDrawable active=new android.graphics.drawable.GradientDrawable();active.setColor(ui.tokens.accent);active.setCornerRadius(ui.dp(ui.tokens.cardRadius));holder.body.setBackground(active);}else holder.body.setBackground(GlassSurface.of(SettingsPresetPickerActivity.this,ui.tokens.cardRadius,false));holder.body.setActivated(selected);GlassTypography.apply(holder.name,selected?700:600);recycled.setContentDescription(holder.name.getText()+", "+holder.detail.getText());recycled.setSelected(selected);return recycled;}}
    private static final class RowHolder {LinearLayout body;TextView name,detail;}
}
